package com.salespunch360.mobile
import android.app.Application;import androidx.lifecycle.AndroidViewModel;import androidx.lifecycle.viewModelScope;import com.salespunch360.mobile.data.*;import java.io.IOException;import kotlinx.coroutines.flow.*;import kotlinx.coroutines.launch;import kotlinx.serialization.json.*
data class ExpenseCategoryState(val loading:Boolean=false,val saving:Boolean=false,val query:String="",val categories:List<JsonObject> = emptyList(),val ledgers:List<JsonObject> = emptyList(),val editing:JsonObject?=null,val error:String?=null)
class ExpenseCategoryViewModel(app:Application):AndroidViewModel(app){private val api=ApiClient(SecureSession(app));private val _state=MutableStateFlow(ExpenseCategoryState());val state:StateFlow<ExpenseCategoryState> = _state;init{load()};fun load()=viewModelScope.launch{_state.value=_state.value.copy(loading=true,error=null);try{val x=api.expenseCategories(_state.value.query);_state.value=_state.value.copy(loading=false,categories=x["categories"]?.jsonArray?.map{it.jsonObject}.orEmpty(),ledgers=x["ledgers"]?.jsonArray?.map{it.jsonObject}.orEmpty())}catch(e:Exception){fail(e)}};fun search(q:String){_state.value=_state.value.copy(query=q);load()};fun edit(x:JsonObject=buildJsonObject{}){_state.value=_state.value.copy(editing=x)};fun close(){_state.value=_state.value.copy(editing=null)};fun save(p:JsonObject)=viewModelScope.launch{try{api.saveExpenseCategory(_state.value.editing?.get("id")?.jsonPrimitive?.contentOrNull,p);close();load()}catch(e:Exception){fail(e)}};fun disable(id:String)=viewModelScope.launch{try{api.disableExpenseCategory(id);load()}catch(e:Exception){fail(e)}};private fun fail(e:Exception){_state.value=_state.value.copy(loading=false,saving=false,error=if(e is IOException)"Offline. No category change was confirmed." else "Category action rejected by server.")}}
